"""Generate bold, non-condensed ASCII glyphs with a slashed zero."""
from pathlib import Path
from PIL import Image, ImageDraw, ImageFont
ROOT=Path(__file__).resolve().parents[1]
lines=['// Cousine Bold, SIL OFL 1.1; see third_party/fonts/Cousine-OFL.txt.',
       '// Generated by tools/generate_readable_fonts.py. Zero has an explicit slash.',
       '#pragma once']
for size in (9,10,11,12,13,18):
    font=ImageFont.truetype(str(ROOT/'third_party/fonts/Cousine-Bold.ttf'),size)
    pixels=[];glyphs=[]
    for code in range(32,127):
        char=chr(code);left,top,right,bottom=font.getbbox(char,anchor='la')
        im=Image.new('L',(max(1,right-left),max(1,bottom-top)),0)
        ImageDraw.Draw(im).text((-left,-top),char,font=font,fill=255,anchor='la')
        im=im.point(lambda p:255 if p>=105 else 0)
        bounds=im.getbbox()
        if bounds:
            left+=bounds[0];top+=bounds[1];im=im.crop(bounds);w,h=im.size
            if char=='0' and w>=4 and h>=5:
                ImageDraw.Draw(im).line((1,h-2,w-2,1),fill=255,width=1)
        else:w=h=0
        glyphs.append((len(pixels),w,h,left,top,round(font.getlength(char)*64)))
        for y in range(h):
            for start in range(0,w,8):
                byte=0
                for bit in range(8):
                    if start+bit<w and im.getpixel((start+bit,y)):byte|=128>>bit
                pixels.append(byte)
    name=f'readable_font{size}'
    lines.append(f'static const uint8_t {name}_pixels[] PROGMEM = {{')
    lines += [','.join(map(str,pixels[i:i+24]))+',' for i in range(0,len(pixels),24)]
    lines.append('};');lines.append(f'static const UiGlyph {name}_glyphs[] PROGMEM = {{')
    lines += ['{'+','.join(map(str,g))+'},' for g in glyphs]
    lines.append('};');lines.append(f'static const UiFont {name} = {{{name}_glyphs,{name}_pixels}};')
(ROOT/'src/readable_fonts.h').write_text('\n'.join(lines)+'\n')
print('Generated Cousine Bold ASCII fonts: 9/10/11/12/13/18px, slashed zero')
